"use client";
import Component from "../smoothui/AnimatedFileUpload";
import { useState } from "react";
import { DemoFrame } from "../shared/DemoFrame";
export default function Demo() {
  const [names, setNames] = useState<string[]>([]);
  return (
    <DemoFrame
      hint={
        names.length
          ? `${names.length} files selected locally`
          : "Choose a file to try the interaction. Files stay on this device."
      }
    >
      <Component
        className="w-full max-w-md"
        multiple
        onFilesSelected={(files) => setNames(files.map((f) => f.name))}
      />
    </DemoFrame>
  );
}

/** Example and adapters: Copyright (c) 2026 NikroZorkin. MIT; licenses/elements.txt. */
import type { ReactNode } from "react";

/** Layout for this example only. The component itself has no catalog dependency. */
export function DemoFrame({
  children,
  className = "",
  hint,
}: {
  children: ReactNode;
  className?: string;
  hint?: string;
}) {
  return (
    <div
      className={`relative flex min-h-[420px] w-full flex-col items-center justify-center gap-7 overflow-hidden p-8 ${className}`}
